SIM = {
  duration: 1.21160132,
  bodies: [
    { id: "M", at: function (s) { const b = s.M; return [b.x, b.y]; } },
    { id: "N", at: function (s) { const b = s.N; return [b.x, b.y]; } }
  ],
  phases: [{ t0: 0, t1: 0.35124074 }, { t0: 0.35124074, t1: 1.21160132 }],
};

slots.drawFrame:
const th = Math.PI / 6;
const ux = Math.cos(th), uy = Math.sin(th);
const halfW = 0.2;   // 物块沿斜面方向半宽

// ── 静止场景：斜面（顶点在右上，坡脚在左下）+ 水平地面 ──
Draw.incline([1.7, 0.8], { angleDeg: -30, length: 3.4 });
Draw.ground(-2.7, -1.2, -0.9);

// ── 已走过轨迹 ──
const ptsM = [];
const ptsN = [];
for (let tt = 0; tt <= t; tt += 0.03) {
  const s = context.at(tt);
  ptsM.push([s.M.x, s.M.y]);
  ptsN.push([s.N.x, s.N.y]);
}
if (ptsM.length > 1) Draw.trace(ptsM);

// N 先静止后才运动，去掉原地重复点
const nTrace = [];
for (let i = 0; i < ptsN.length; i++) {
  if (nTrace.length === 0) {
    nTrace.push(ptsN[i]);
  } else {
    const p = nTrace[nTrace.length - 1];
    const dx = ptsN[i][0] - p[0], dy = ptsN[i][1] - p[1];
    if (dx * dx + dy * dy > 1e-4) nTrace.push(ptsN[i]);
  }
}
if (nTrace.length > 1) Draw.trace(nTrace);

// ── 弹簧：两端分别贴到 M、N 相向的端面 ──
const mC = [state.M.x, state.M.y];
const nC = [state.N.x, state.N.y];
Draw.spring(
  [mC[0] - halfW * ux, mC[1] - halfW * uy],
  [nC[0] + halfW * ux, nC[1] + halfW * uy],
  { coils: 10 }
);

// ── 物块（沿斜面倾斜 30°） ──
Draw.box(nC, 0.4, 0.3, { angleDeg: 30 });
Draw.box(mC, 0.4, 0.3, { angleDeg: 30 });

slots.readouts:
// 由 analysis 运动表生成；曲线图直接读这里
const out = [];
const h = 1e-4;
const tA = Math.max(0, t - h);
const tB = Math.min(1.21160132, t + h);
const a = stateAt(tA);
const b = stateAt(tB);
const dt = (tB - tA) || 1;
out.push({ key: "M.x", label: "M 水平位置", value: state.M.x, unit: 'm' });
out.push({ key: "M.y", label: "M 竖直位置", value: state.M.y, unit: 'm' });
out.push({ key: "M.vx", label: "M 水平速度", value: (b.M.x - a.M.x) / dt, unit: 'm/s' });
out.push({ key: "M.vy", label: "M 竖直速度", value: (b.M.y - a.M.y) / dt, unit: 'm/s' });
out.push({ key: "N.x", label: "N 水平位置", value: state.N.x, unit: 'm' });
out.push({ key: "N.y", label: "N 竖直位置", value: state.N.y, unit: 'm' });
out.push({ key: "N.vx", label: "N 水平速度", value: (b.N.x - a.N.x) / dt, unit: 'm/s' });
out.push({ key: "N.vy", label: "N 竖直速度", value: (b.N.y - a.N.y) / dt, unit: 'm/s' });
return out;
